/**
 * Pure helpers that turn our signer records into DocuSign envelope parts.
 *
 * - Every signer is delivered by Email with an additional SMS notification
 *   (countryCode "1") unless the envelope is "email only".
 * - All signers have routingOrder 1 (they sign in parallel).
 * - Documents are generated by our server (one per signer) — no templateRoles,
 *   which don't support additionalNotifications.
 */
import type { DsAnchorTab, DsSigner } from "./api";
import { anchorsFor } from "./documents";

/** DocuSign's per-envelope SMS-recipient ceiling we split on. */
export const MAX_SMS_SIGNERS_PER_ENVELOPE = 10;

export interface SignerLike {
  id: number;
  role: "member" | "guest" | string;
  fullName: string;
  email: string;
  phone: string | null;
}

export function smsNotification(phone: string | null | undefined, emailOnly: boolean): DsSigner["additionalNotifications"] {
  if (emailOnly || !phone) return undefined;
  return [{ secondaryDeliveryMethod: "SMS", phoneNumber: { countryCode: "1", number: phone } }];
}

function anchorTab(documentId: string, anchorString: string, x: number, y: number): DsAnchorTab {
  return { documentId, anchorString, anchorUnits: "pixels", anchorXOffset: String(x), anchorYOffset: String(y), anchorIgnoreIfNotPresent: "false" };
}

/** A DocuSign signer for one of our signer records, with tabs on their own document. */
export function toDsSigner(s: SignerLike, documentId: string, emailOnly: boolean): DsSigner {
  const recipientId = String(s.id);
  const a = anchorsFor(recipientId);
  return {
    recipientId,
    routingOrder: "1",
    name: s.fullName,
    email: s.email,
    deliveryMethod: "Email",
    additionalNotifications: smsNotification(s.phone, emailOnly),
    tabs: {
      signHereTabs: [anchorTab(documentId, a.signature, 0, -8)],
      fullNameTabs: [anchorTab(documentId, a.name, 0, -4)],
      dateSignedTabs: [anchorTab(documentId, a.date, 0, -4)],
    },
  };
}

/**
 * Split signers into envelopes. One envelope normally; when more than
 * MAX_SMS_SIGNERS_PER_ENVELOPE signers would get SMS, guests are split into
 * extra envelopes of up to 10 — the member is always in the first.
 */
export function splitSignersIntoEnvelopes<T extends SignerLike>(signers: T[], opts: { emailOnly: boolean }): T[][] {
  const member = signers.filter((s) => s.role === "member");
  const guests = signers.filter((s) => s.role !== "member");
  const ordered = [...member, ...guests];
  const smsCount = opts.emailOnly ? 0 : ordered.filter((s) => !!s.phone).length;
  if (smsCount <= MAX_SMS_SIGNERS_PER_ENVELOPE) return ordered.length ? [ordered] : [];
  const chunks: T[][] = [];
  for (let i = 0; i < ordered.length; i += MAX_SMS_SIGNERS_PER_ENVELOPE) {
    chunks.push(ordered.slice(i, i + MAX_SMS_SIGNERS_PER_ENVELOPE));
  }
  return chunks;
}

/** Map a DocuSign recipient status to ours. */
export type OurSignerStatus = "queued" | "sent" | "viewed" | "signed" | "declined" | "expired" | "voided" | "failed" | "removed";
export function mapRecipientStatus(ds: string): OurSignerStatus | null {
  switch (String(ds).toLowerCase()) {
    case "created": return null; // not yet sent; leave as-is
    case "sent": return "sent";
    case "delivered": return "viewed";
    case "signed":
    case "completed": return "signed";
    case "declined": return "declined";
    case "autoresponded": return "failed"; // delivery bounced
    default: return null;
  }
}

/** Status precedence so an out-of-order event can't move a signer backwards. */
const RANK: Record<string, number> = { queued: 0, failed: 1, sent: 2, viewed: 3, declined: 4, signed: 5, expired: 6, voided: 6, removed: 7 };
export function shouldAdvance(current: string, next: string): boolean {
  if (current === next) return false;
  if (["signed", "removed", "voided", "expired"].includes(current)) return false;
  // A declined signer may still sign after a correction/resend.
  if (current === "declined") return next === "signed" || next === "sent" || next === "viewed";
  return (RANK[next] ?? 0) >= (RANK[current] ?? 0) || current === "failed";
}
